def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    points = sorted({x for op in ops for x in (op[1], op[2] + 1)})
    index = {x: i for i, x in enumerate(points)}
    m = len(points) - 1

    # Minimum and maximum colour in each segment; zero means blank.
    minimum = [0] * (4 * m + 4)
    maximum = [0] * (4 * m + 4)
    lazy = [0] * (4 * m + 4)

    def assign(node: int, colour: int) -> None:
        minimum[node] = colour
        maximum[node] = colour
        lazy[node] = colour

    def push(node: int) -> None:
        colour = lazy[node]
        if colour != -1:
            assign(node * 2, colour)
            assign(node * 2 + 1, colour)
            lazy[node] = -1

    def update(
        node: int, left: int, right: int,
        query_left: int, query_right: int, colour: int, erase: bool
    ) -> None:
        if query_left <= left and right <= query_right:
            if erase or maximum[node] <= colour:
                assign(node, colour)
                return
            if minimum[node] >= colour:
                return

        push(node)
        mid = (left + right) // 2
        if query_left <= mid:
            update(node * 2, left, mid, query_left, query_right, colour, erase)
        if query_right > mid:
            update(node * 2 + 1, mid + 1, right, query_left, query_right, colour, erase)
        minimum[node] = min(minimum[node * 2], minimum[node * 2 + 1])
        maximum[node] = max(maximum[node * 2], maximum[node * 2 + 1])

    for op in ops:
        left = index[op[1]]
        right = index[op[2] + 1] - 1
        if op[0] == 0:
            update(1, 0, m - 1, left, right, 0, True)
        else:
            update(1, 0, m - 1, left, right, op[3], False)

    counts = {}

    def collect(node: int, left: int, right: int) -> None:
        if minimum[node] == maximum[node]:
            colour = minimum[node]
            if colour:
                counts[colour] = counts.get(colour, 0) + points[right + 1] - points[left]
            return
        mid = (left + right) // 2
        collect(node * 2, left, mid)
        collect(node * 2 + 1, mid + 1, right)

    collect(1, 0, m - 1)
    return [[colour, counts[colour]] for colour in sorted(counts)]
